body.usercss:

    .btn-css {
        position: absolute;
        height: 50px;
        background: white;
        right: 15px;
        z-index: 3;
    }

    /* 탭바 영역 CSS */

    .font-size-13 {
        font-size: 13px;
    }

    .font-size-14 {
        font-size: 14px;
    }

    .table-default-width {
        width: 100%;
        table-layout: fixed;
        border-collapse: collapse;
    }

    .table-td-subject {
        font-size: 13px;
        color: #797979;
        text-align: center;
    }

    .table-td-header {
        font-size: 13px;
        text-align: center;
    }

    .table-line1 {
        width: 70px;
        text-align: center;
    }

    .table-line2 {
        width: 45px;
        text-align: left;
        text-overflow: ellipsis;
		overflow: hidden;
		white-space: nowrap;
    }

    .table-line3 {
        width: 60px;
    }

    .table-line4 {
        width: 90px;
        padding: 3px;
    }

    .table-line4-align {
        text-align: center;
    }

    .table-line5 {
        width: 65px;
    }

    .table-line6 {
        width: 30px;
        vertical-align: initial;
        padding: 3px;
    }

    .detail-line {
        padding-top: 15px;
        padding-left: 4px;
    }

    /* 폼 영역 CSS */

    .form-table {
        width: 100%;
        margin-bottom: 10px;
        margin-top: 20px;
    }

    .form-subject {
        font-size: 14px;
        color: #222222;
    }

    .table-attach {
        margin-top: 15px;
    }

    .form-padding {
        padding-top: 15;
    }

    .custom-vertical {
        vertical-align: middle;
    }

    .text-area {
        width: 99%;
        resize: none;
        font-size: 12px;
        color: #222222;
        border-color: #d7d7d7;
        outline: #d7d7d7;
        padding: 5px;
    }

    .text-area-height {
        height: 20px;
    }

    .text-area-height-custom {
        height: 100px;
    }

    .text-area-margin {
        margin-top: 5px;
        margin-bottom: 10px;
    }

    .text-area-margin2 {
        margin-top: 5px;
    }

    .form-checkbox {
        font-size: 12px;
        margin-left: 10px;
    }

    .checkBox-margin {
        margin: 0;
    }

    .subject-margin {
        width: 100%;
        margin-top: 15px;
    }

    .hr-line {
    	width: 100%; 
    	height: 14px;
    	background-color: #f1f1f1;
    	border: 0;
    }

userscript.function:

            config = data

            if(config.reload){
            	config.reload = true
            } else{
            	config.reload = false;
            }

            var smrNumber = config.SMR_NUMBER;
            var appNo = config.APP_NO;
            var appNoSeq = config.APP_NO_SEQ;

            var params = {
                COMPANY_CODE: Sepoa.info.COMPANY_CODE,
                SMR_NUMBER: smrNumber,
                APP_NO: appNo,
                APP_NO_SEQ: appNoSeq,
                APPLY_TYPE: "C",
                SCREEN_TYPE: "M"
            };

            var appLineData = {};
            var referenceLineData = {};
            doServiceAjax('sepoa.svc.approval.SepoaApprovalService', 'CONNECTION', 'getAppLine', params, function(so) {
                if (so.status == 1) {
                    sf = new SepoaFormater(so.result[0]);

                    var appSize = 0;
                    var referenceSize = 0;
                    for (var i = 0; i < sf.getRowCount(); i++) {
                        if (sf.dataMap.APP_METHOD[i] != '03') {
                            appSize++
                        } else {
                            referenceSize++
                        }
                    }
                    // 결재선 테이블
                    for (var i = 0; i < sf.getRowCount(); i++) {
                        if (sf.dataMap.APP_METHOD[i] != '03') {
                            appLineData.headerFlag = false;
                            appLineData.endFlag = false;
                            appLineData.detailFlag = false;

                            if (i == 0) {
                                appLineData.headerFlag = true
                            } else if (i == appSize - 1) {
                                appLineData.endFlag = true
                            }

                            if (sf.dataMap.ACCEPT_REASON[i] != '') {
                                appLineData.detailFlag = true;
                            }

                            var year = sf.dataMap.ACCEPT_DATE[i].substring(0, 4);
                            var month = sf.dataMap.ACCEPT_DATE[i].substring(4, 6);
                            var day = sf.dataMap.ACCEPT_DATE[i].substring(6, 8);
                            var acceptDate = year + "/" + month + "/" + day;

                            if (sf.dataMap.ACCEPT_DATE[i] == '') acceptDate = '';
                            appLineData.APP_LINE_STATUS = sf.dataMap.APP_LINE_STATUS[i]
                            appLineData.APP_METHOD = sf.dataMap.APP_METHOD[i]
                            appLineData.APP_USER_ID = sf.dataMap.APP_USER_ID[i]
                            appLineData.APP_USER_NAME = sf.dataMap.APP_USER_NAME[i]
                            appLineData.APP_USER_DEPT_NAME = sf.dataMap.APP_USER_DEPT_NAME[i]
                            appLineData.ACCEPT_DATE = acceptDate
                            appLineData.ACCEPT_REASON = sf.dataMap.ACCEPT_REASON[i]
                            appLineData.TABLE_ROW = i;
                            appLineData.reload = config.reload

                            // 결재대기자의 ID가 세션값과 다를경우 버튼숨김
                            if(sf.dataMap.APP_LINE_STATUS[i] == 'L04'){
                            	confirmUser =  sf.dataMap.APP_USER_ID[i];
                            	if(confirmUser != Sepoa.info.ID){
                            		btnObj.btn('confirm').setHide();
                					btnObj.btn('reject').setHide();
                            	}
                            }
                            drawTabbarAppLine(appLineData)
                        }
                    }
                    referenceHeaderDraw();
                    for (var i = 0; i < sf.getRowCount(); i++) {
                        if (sf.dataMap.APP_METHOD[i] == '03') {
                            referenceLineData.headerFlag = false;
                            referenceLineData.endFlag = false;
                            referenceLineData.detailFlag = false;

                            if (i == (sf.getRowCount() - referenceSize)) {
                                referenceLineData.headerFlag = true
                            } else if (i == sf.getRowCount() - 1) {
                                referenceLineData.endFlag = true
                            }


                            referenceLineData.APP_LINE_STATUS = sf.dataMap.APP_LINE_STATUS[i]
                            referenceLineData.APP_METHOD = sf.dataMap.APP_METHOD[i]
                            referenceLineData.APP_USER_ID = sf.dataMap.APP_USER_ID[i]
                            referenceLineData.APP_USER_NAME = sf.dataMap.APP_USER_NAME[i]
                            referenceLineData.APP_USER_DEPT_NAME = sf.dataMap.APP_USER_DEPT_NAME[i]
                            referenceLineData.ACCEPT_DATE = sf.dataMap.ACCEPT_DATE[i]
                            referenceLineData.ACCEPT_REASON = sf.dataMap.ACCEPT_REASON[i]
                            referenceLineData.TABLE_ROW = i;
                            referenceLineData.reload = config.reload;

                            drawTabbarReference(referenceLineData);
                        }
                    }
                }
            });
			if(!config.reload){
            	getReqSealInfo(config, params);
            }


			doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectRequestInfo', params, function(so) {
                if (so.status == 1) {
                    var reqData = JSON.parse(so.result[0]);
                    var docList = reqData[0].DOCUMENT_LIST;
                    	reqSealInfo = reqData[0].REQ_SEAL_INFO;
                    	sealList = reqData[0].SELECTED_SEAL_LIST;
                    var attachList = reqData[0].ATTACH_DOCUMENT_LIST;
                    var otherFileList = reqData[0].OTHER_FILE_LIST;
					smrStatus = reqData[0].REQ_SEAL_INFO.SMR_STATUS;

                    drawForm(reqSealInfo);

                    var docData = {};
                    for (var i = 0; i < docList.length; i++) {
                        var sealName = [];
                        for (var k in sealList) {
                            if (docList[i].SMD_NUMBER == sealList[k].SMD_NUMBER) {
                                sealName.push(sealList[k].SUBJECT);
                            }
                        }

                        var otherFileName = [];
                        for (var j in otherFileList) {
                            if (docList[i].OTHER_FILE_NO == otherFileList[j].ATTACH_KEY) {
                                otherFileName.push(otherFileList[j].SRC_FILE_NAME);
                            }
                        }
                        docData.SEAL_NAME = sealName;
                        docData.headerFlag = (i == 0) ? true : false;
                        docData.SEAL_TYPE = docList[i].SEAL_TYPE;
                        docData.SUBJECT = docList[i].SUBJECT;
                        docData.COUNT = docList[i].COUNT;
                        docData.SMR_NUMBER = docList[i].SMR_NUMBER;
                        docData.SMD_NUMBER = docList[i].SMD_NUMBER;
                        docData.RE_FLAG = docList[i].RE_FLAG;
                        docData.OTHER_FILE_CNT = docList[i].OTHER_FILE_CNT;
                        docData.OTHER_FILE_NO = docList[i].OTHER_FILE_NO;
                        docData.OTHER_FILE_NAME = otherFileName;
                        docData.TABLE_ROW = i;
                        drawDocTemplate(docData); // 날인대상서류
                    }

                    if (sUtils.workflow.check('USW1665473167170')) { // 사용인감 교부서류
                        var attachData = {};
                        for (var i in attachList) {
                            if (i == 0) {
                                attachData.headerFlag = true;
                            } else {
                                attachData.headerFlag = false;
                            }
                            attachData.SMI_NUMBER = attachList[i].SMI_NUMBER;
                            attachData.REAL_DOC_CHK = attachList[i].REAL_DOC_CHK;
                            attachData.COUNT = attachList[i].COUNT;
                            attachData.CONTENTS = attachList[i].CONTENTS;
                            attachData.TABLE_ROW = i;
                            drawAttacTemplate(attachData); // 교부요청서류
                        }
                    }
                    drawNote(reqSealInfo);
                    callFunction('APM_101', 'changeHeader', [reqSealInfo.SUBJECT]);
                }
            });


            if(data.reload == true){
        		tableRow = "_R_" + data.TABLE_ROW
        	}else {
	            tableRow = "_" + data.TABLE_ROW
            }

            var APP_LINE_STATUS = 'APP_LINE_STATUS' + tableRow;
            var APP_METHOD = 'APP_METHOD' + tableRow
            var APP_USER_ID = 'APP_USER_ID' + tableRow
            var APP_USER_NAME = 'APP_USER_NAME' + tableRow
            var APP_USER_DEPT_NAME = 'APP_USER_DEPT_NAME' + tableRow
            var APP_IMG = 'APP_IMG' + tableRow
            var ACCEPT_DATE = 'ACCEPT_DATE' + tableRow
            var ACCEPT_REASON = 'ACCEPT_REASON' + tableRow
            var ACCEPT_DETAIL = 'ACCEPT_DETAIL' + tableRow
            var BTN_ID = 'BTN_ID' + tableRow
            var BTN_FLAG = data.detailFlag;

            var imgLink;
            if (data.detailFlag) {
                imgLink = 'https://files.axshare.com/gsc/6OZEAA/c0/cf/09/c0cf091e4d4d4bff853870f4b9dc3220/images/날인신청_조회/u71.svg?pageId=a7031c67-0f86-4c42-aecd-f1fcea24f962'
            } else {
                imgLink = 'https://files.axshare.com/gsc/6OZEAA/c0/cf/09/c0cf091e4d4d4bff853870f4b9dc3220/images/날인신청_조회/u86.svg?pageId=a7031c67-0f86-4c42-aecd-f1fcea24f962';
            }

            var appLineTable = '';
            appLineTable += '<div>'
            appLineTable += '<hr>'

            if (data.headerFlag) {
                appLineTable += '<table class="table-default-width">'
                appLineTable += '<tr>'
                appLineTable += '<td class="font-size-13 table-line1">결재상태</td>'
                appLineTable += '<td class="font-size-13 table-line2">결재자</td>'
                appLineTable += '<td class="table-td-header table-line3">담당부서</td>'
                appLineTable += '<td class="font-size-13 table-line4 table-line4-align">처리일자</td>'
                appLineTable += '<td class="table-td-header table-line5">상신의견</td>'
                appLineTable += '</tr>'
                appLineTable += '</table>'
                appLineTable += '<hr>'
            }

            appLineTable += '<table class="table-default-width">'
            appLineTable += '<tr>'
            appLineTable += '<td id="' + APP_LINE_STATUS + '"class="table-td-subject table-line1"></td>'
            appLineTable += '<td id="' + APP_USER_NAME + '"class="font-size-13 table-line2"></td>'
            appLineTable += '<td id="' + APP_USER_DEPT_NAME + '"class="table-td-subject table-line3"></td>'
            appLineTable += '<td id="' + ACCEPT_DATE + '"class="font-size-13 table-line4 table-line4-align"></td>'
            appLineTable += '<td class="table-td-subject table-line5"><img id="' + APP_IMG + '" src="' + imgLink + '"><input id="' + BTN_ID + '" type="hidden" value="' + BTN_FLAG + '"></td>'
            appLineTable += '</tr>'
            appLineTable += '</table>'

            appLineTable += '<table class="table-default-width">'
            appLineTable += '<tr id="' + ACCEPT_DETAIL + '" style="display: none;">'
            appLineTable += '<td class="table-td-subject detail-line">결재 의견</td>'
            appLineTable += '<td id="' + ACCEPT_REASON + '" colspan="4" class="font-size-13 detail-line"></td>'
            appLineTable += '</tr>'
            appLineTable += '</table>'

            if (data.endFlag) {
                appLineTable += '<hr>'
            }

            //div 생성
            var appLineOuter = document.createElement("div");
            appLineOuter.id = "appLineOuter"
            appLineOuter.className = "app-line-outer";

            // 탭바에 테이블추가
            appLineOuter.appendChild($(appLineTable)[0]);
            tabbarObj.tabs('appLine').appendObject(appLineOuter);

            // 데이터세팅
            var setLineData = {};
            setLineData.APP_LINE_STATUS = document.getElementById(APP_LINE_STATUS);
            setLineData.APP_USER_NAME = document.getElementById(APP_USER_NAME);
            setLineData.APP_USER_DEPT_NAME = document.getElementById(APP_USER_DEPT_NAME);
            setLineData.ACCEPT_DATE = document.getElementById(ACCEPT_DATE);
            setLineData.ACCEPT_REASON = document.getElementById(ACCEPT_REASON);

            for (var i in setLineData) {
                for (var k in data) {
                    if (i == k && setLineData[i] != null) {
                        setLineData[i].innerText = data[i];
                    }
                }
            }

            var useArray = Sepoa.cache.combo.get('SL0001,' + Sepoa.info.HOUSE_CODE + '#' + Sepoa.info.LANGUAGE + '#' + 'AP008');
            var useName = useArray.find((item, idx) => {
                return item.value == data.APP_LINE_STATUS;
            });
            //null값 예외처리
            if (!useName) {
                useName = {
                    text: ''
                };
            }
            setLineData.APP_LINE_STATUS.innerText = useName.text;
            if (useName.value == 'L03' || useName.value == 'L05') {
                btnObj.btn('confirm').setHide();
                btnObj.btn('reject').setHide();
            }
            // 클릭이벤트 
            $(document).on('click', '#' + APP_IMG, function() {
                var flag = document.getElementById(BTN_ID);
                if (flag.value == 'true') {
                    $('#' + ACCEPT_DETAIL).toggle();
                }
            });


	var referenceTable = '';
    referenceTable += '<div>'
    referenceTable += '<hr>'

	referenceTable += '<table class="table-default-width">'
    referenceTable += '<tr>'
    referenceTable += '<td class="table-td-subject table-line1">결재상태</td>'
    referenceTable += '<td class="font-size-13 table-line2">결재자</td>'
    referenceTable += '<td class="table-td-subject table-line3">담당부서</td>'
    referenceTable += '<td class="font-size-13 table-line4 table-line4-align">승인날짜</td>'
    referenceTable += '<td class="table-td-subject table-line5">상신의견</td>'
    referenceTable += '</tr>'
    referenceTable += '</table>'
    referenceTable += '<hr>'
    referenceTable += '</div>'


	var referenceOuter = document.createElement("div");
    referenceOuter.id = "referenceOuter"
    referenceOuter.className = "reference-line-outer";

    // 탭바에 테이블추가
    referenceOuter.appendChild($(referenceTable)[0]);
    tabbarObj.tabs('reference').appendObject(referenceOuter);


tableRow = "_" + data.TABLE_ROW
var REF_APP_METHOD = 'REF_LINE_STATUS' + tableRow;
